import static org.mockito.Mockito.when;

public class BuildGlobalNamespace_shouldTraverse_TriageGen1Test {

    private BuildGlobalNamespace buildGlobalNamespace;
    private NodeTraversal t;
    private Node n;
    private Node parent;
    private Node externsRoot;
    private Scope scope;
    private JSModule module;

    @Before
    public void setUp() throws Exception {
        buildGlobalNamespace = new BuildGlobalNamespace();
        t = mock(NodeTraversal.class);
        n = mock(Node.class);
        parent = mock(Node.class);
        externsRoot = mock(Node.class);
        scope = mock(Scope.class);
        module = mock(JSModule.class);

        // Setup common mock behavior
        when(t.getScope()).thenReturn(scope);
        when(t.getModule()).thenReturn(module);

        // Use reflection to set private fields since they are not exposed via constructor
        setPrivateField(buildGlobalNamespace, "externsRoot", externsRoot);
    }

    @Test
    public void testShouldTraverse_WhenExternsRootMatches() {
        // Arrange: n is the externsRoot
        when(n, org.mockito.Mockito.equals(externsRoot)).thenReturn(true); 
        // Note: In real Mockito, we'd use when(n).equals(externsRoot). 
        // Since n is a mock, we ensure the identity check works.

        // We need to simulate the identity check (n == externsRoot)
        // Because n and externsRoot are different mock instances, 
        // we must make them the same instance or use a spy if identity is strict.
        // Let's re-setup for this specific branch.
        n = externsRoot; 

        // Act
        boolean result = buildGlobalNamespace.shouldTraverse(t, n, parent);

        // Assert
        assertTrue(result);
        verify(buildGlobalNamespace).collect(module, scope, n);
        // Verify externsScope was set (checking via reflection)
        Object externsScope = getPrivateField(buildGlobalNamespace, "externsScope");
        org.junit.Assert.assertEquals(scope, externsScope);
    }

    @Test
    public void testShouldTraverse_WhenExternsRootDoesNotMatch() {
        // Arrange: externsRoot is set but n is a different node
        // n is already a different mock from externsRoot from setUp

        // Act
        boolean result = buildGlobalNamespace.shouldTraverse(t, n, parent);

        // Assert
        assertTrue(result);
        verify(buildGlobalNamespace).collect(module, scope, n);
        // Verify externsScope remains null
        Object externsScope = getPrivateField(buildGlobalNamespace, "externsScope");
        org.junit.Assert.assertNull(externsScope);
    }

    @Test
    public void testShouldTraverse_WhenExternsRootIsNull() {
        // Arrange: externsRoot is null
        setPrivateField(buildGlobalNamespace, "externsRoot", null);

        // Act
        boolean result = buildGlobalNamespace.shouldTraverse(t, n, parent);

        // Assert
        assertTrue(result);
        verify(buildGlobalNamespace).collect(module, scope, n);
        Object externsScope = getPrivateField(buildGlobalNamespace, "externsScope");
        org.junit.Assert.assertNull(externsScope);
    }

    // Helper methods to handle private field access for testing internal state
    private void setPrivateField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private Object getPrivateField(Object target, String fieldName) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            return field.get(target);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
